    private static final String TARGET="objects/model.iob",JSON="future/unknown.json";
    private static byte[] bytes(String text) { return text.getBytes(StandardCharsets.UTF_8); }
    private static void check(boolean valid,String reason) { if (!valid) throw new AssertionError("Asset replacement: "+reason); }
    @FunctionalInterface private interface Action { void run() throws Exception; }
    private static void rejects(Action action) throws Exception { try { action.run(); } catch (IOException | IllegalArgumentException | IllegalStateException | NullPointerException expected) { return; }throw new AssertionError("Expected rejected asset operation"); }
    private static PackWorkspace pack() throws Exception { var files=new LinkedHashMap<String,byte[]>();files.put(TARGET,new byte[]{1,0,-1});files.put("images/picture.PNG",new byte[]{0,3,-1});files.put("images/photo.jpg",new byte[]{4,5});files.put(JSON,bytes("{\"future\":9007199254740993,\"literal\":\"雪\\u0061\"}\r\n"));files.put("other/opaque.bin",new byte[]{0,5,-1});return PackWorkspace.newPack(files); }
    private static Path write(Path folder,String name,byte[] data) throws Exception { Path path=folder.resolve(name);Files.write(path,data);return path; }
    private static String hash(byte[] data) throws Exception { return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(data)); }
    private static AssetReplacement.Prepared capture(Path path,String target) throws Exception { return AssetReplacement.prepare(path,target,AssetImports.MAX_BYTES,() -> false); }
    private static void await(CountDownLatch latch,String reason) throws Exception { check(latch.await(10,TimeUnit.SECONDS),reason); }
    private static void stop(Thread worker) throws Exception { worker.join(10_000);check(!worker.isAlive(),"worker exits after reader returns"); }
    private static java.util.concurrent.ThreadFactory threads(AtomicReference<Thread> thread) { return runnable -> { var worker=new Thread(runnable,"test-asset-capture");thread.set(worker);return worker; }; }
    private static AsyncAssetReplacement.Snapshot terminal(AsyncAssetReplacement replacement,PackWorkspace current) {
        long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(10);
        while (System.nanoTime()<deadline) { var state=replacement.poll(current);if (state.phase()!=AsyncAssetReplacement.Phase.CAPTURING) return state;LockSupport.parkNanos(1_000_000); }
        throw new AssertionError("Asset capture did not finish");
    }
