    private static void boundaries(Path temp) throws Exception {
        int half=16*1024*1024;byte[] before=new byte[half];before[0]=1;var current=PackWorkspace.newPack(Map.of(TARGET,before,JSON,bytes("{}")));current.replace(JSON,bytes("changed"));Path source=temp.resolve("large.iob");try (var file=new RandomAccessFile(source.toFile(),"rw")) { file.setLength(half);file.write(2); }
        var exact=capture(source,TARGET);var target=AssetReplacement.target(current,TARGET);check(AssetReplacement.fitsHistory(target,exact.receipt()) && AssetReplacement.apply(current,target,exact,false) && current.historyBytes()==AppliedEditHistory.MAX_BYTES && current.undoCount()==1,"exact 32 MiB retained-edit bound with normal eviction");current.undo();
        try (var file=new RandomAccessFile(source.toFile(),"rw")) { file.setLength(half+1);file.write(3); }var tooLarge=capture(source,TARGET);var next=AssetReplacement.target(current,TARGET);long revision=current.revision();int history=current.undoCount()+current.redoCount();check(!AssetReplacement.fitsHistory(next,tooLarge.receipt()),"over-budget receipt requires acknowledgement");rejects(() -> AssetReplacement.apply(current,next,tooLarge,false));check(current.revision()==revision && current.undoCount()+current.redoCount()==history,"rejected unrecordable apply preserves bytes and history");check(AssetReplacement.apply(current,next,tooLarge,true) && current.undoCount()+current.redoCount()==0 && current.historyNote().contains("exceeded"),"explicit unrecordable replacement clears history using existing policy");current.replace(JSON,bytes("new history"));var same=AssetReplacement.target(current,TARGET);int keep=current.undoCount();check(!AssetReplacement.apply(current,same,tooLarge,false) && current.undoCount()==keep,"large identical copy needs no acknowledgement and does not clear history");
        Path max=temp.resolve("max.iob");try (var file=new RandomAccessFile(max.toFile(),"rw")) { file.setLength(AssetImports.MAX_BYTES); }var full=capture(max,TARGET);check(full.receipt().bytes()==AssetImports.MAX_BYTES,"exact 64 MiB source accepted without format validation");try (var file=new RandomAccessFile(max.toFile(),"rw")) { file.setLength(AssetImports.MAX_BYTES+1); }rejects(() -> capture(max,TARGET));
    }
    private static final class Gate { final CountDownLatch started=new CountDownLatch(1),release=new CountDownLatch(1);volatile BooleanSupplier cancelled; }
    private static final class Controlled implements AsyncAssetReplacement.Reader {
        final Map<String,Gate> gates;final Thread caller=Thread.currentThread();final AtomicInteger active=new AtomicInteger(),maximum=new AtomicInteger();final List<String> calls=java.util.Collections.synchronizedList(new ArrayList<>());
        Controlled(Map<String,Gate> gates) { this.gates=gates; }
        public AssetReplacement.Prepared read(Path source,String target,long budget,BooleanSupplier cancelled) throws IOException {
            check(Thread.currentThread()!=caller && target.equals(TARGET) && budget<=AssetImports.MAX_BYTES,"worker gets only immutable path/budget metadata away from UI thread");String name=source.getFileName().toString();var gate=gates.get(name);gate.cancelled=cancelled;calls.add(name);int count=active.incrementAndGet();maximum.accumulateAndGet(count,Math::max);gate.started.countDown();
            try { long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(10);boolean released=false;while (!released && System.nanoTime()<deadline) try { released=gate.release.await(20,TimeUnit.MILLISECONDS); } catch (InterruptedException ignored) { }check(released,"controlled capture released");return AssetReplacement.prepare(source,target,budget,() -> false); } finally { active.decrementAndGet(); }
        }
    }
